import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    f = np.sum((x - 0.2)**2) + 0.1 * np.sum(x**3) + 0.5 * np.sum(np.cos(5 * x))

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    quadratic_term = np.sum((x - 0.2)**2)
    skew_term = 0.1 * np.sum(x**3)
    ripple_term = 0.5 * np.sum(np.cos(5 * x) * np.exp(-0.1 * np.sum(x**2)))

    f = quadratic_term + skew_term + ripple_term

    return float(f)

