import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    quadratic_bowl = np.sum(x**2) + 0.1 * np.sum(x**3)
    cosine_waves = 0.2 * np.sum(np.cos(4 * x))
    linear_term = 0.1 * np.sum(x)

    f = quadratic_bowl + cosine_waves + linear_term

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    f = np.sum((x - 0.2)**2) + 0.1 * np.sum(x**3)
    for i in range(3):
        f -= 0.5 * np.exp(-np.sum((x - i*1.5)**2) / 0.5)
    f += 0.1 * np.log(1 + np.linalg.norm(x)**2)

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    quadratic = np.sum(x**2)
    skew = 0.1 * np.tanh(quadratic) * np.sum(x)
    sinusoid = 0.5 * np.sum(np.cos(3 * x))

    return float(quadratic + skew + sinusoid)

