import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    quadratic_term = np.sum((x + 0.5)**2)
    skew_term = 0.1 * np.sum((x + 0.5)**3)

    sinc_product = 1.0
    for i in range(3):
        if x[i] == 0:
            sinc_product *= 1.0  # sinc(0) = 1
        else:
            sinc_product *= np.sin(x[i]) / x[i]

    gaussian_peak = 0.5 * np.exp(-np.sum((x - [1, -1, 1])**2) / 2)


    f = quadratic_term + skew_term + sinc_product + gaussian_peak
    return float(f)

