import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    abs_sum = np.sum(np.abs(x))
    decaying_oscillation = np.sum(np.cos(5 * x) * np.exp(-0.2 * x**2))
    reciprocal = 0.2 / (1 + np.sum(x**2))
    exponential = 0.1 * np.exp(0.5 * np.sum(x))

    return float(abs_sum + decaying_oscillation + reciprocal + exponential)

