import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    sum_of_squares = np.sum(x**2)
    sine_waves = np.sum(np.sin(5 * x) * np.exp(-0.1 * np.sum(x**2)))
    rational_term = np.clip(0.5 * (x[0] / (1 + x[1]**2 + x[2]**2)), -2, 2)
    f = sum_of_squares + sine_waves + rational_term + 1.5 * np.sum(x)

    return float(f -5)

