import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    exponential_term = np.sum(np.exp(-0.2 * x**2))
    sinusoidal_wave = np.sum(np.sin(3 * x) * np.exp(-0.05 * np.sum(x**2)))

    logarithmic_term = -np.log(1 + np.sum((x + 2)**2))

    f = 2 * exponential_term + 1.5 * sinusoidal_wave + 0.8 * logarithmic_term - 0.1 * np.sum(x) + 5

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    sum_of_squares = np.sum(x**2)
    sine_waves = np.sum(0.1 * np.sin(5 * x))
    rational_term = 0.1 * (x[0] / (1 + x[1]**2 + x[2]**2))
    f = sum_of_squares + sine_waves + rational_term + 0.5 * np.sum(x)

    return float(f - 2)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    sum_of_squares = np.sum((x - 0.5)**2) # shifting the sum of squares
    sine_waves = np.sum(np.sin(5 * x) * np.exp(-0.1 * np.sum(x**2)))
    rational_term = np.clip(0.5 * (x[0] / (1 + x[1]**2 + x[2]**2)), -2, 2)
    f = sum_of_squares + sine_waves + rational_term + 1.5 * np.sum(x) + 0.2*x[0] - 0.1*x[1] # Weighted linear term to shape response surfaces

    return float(f - 5)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    sum_of_squares = np.sum(x**2)
    sine_waves = np.sum(np.sin(5 * x) * np.exp(-0.1 * sum_of_squares))
    rational_term = 0.5 * (x[0] / (1 + x[1]**2 + x[2]**2))

    f = sum_of_squares + sine_waves + rational_term + 0.8 * np.sum(x)

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (3,):
        raise ValueError(f"Expected input of shape (3,), got {x.shape}")

    sum_of_squares = np.sum(x**2)
    sine_waves = np.sum(np.sin(5 * x) * np.exp(-0.1 * sum_of_squares))

    gaussian_scale = np.exp(-0.05 * sum_of_squares)
    f = sum_of_squares - 5 + gaussian_scale * sine_waves + 1.5 * np.sum(x)

    return float(f)
